# Anomaly / alternative-history equivalence with the original (legacy) SIECC scripts on FULLY SYNTHETIC data only (no real data).
# The legacy functions siecc_daily_anomaly_scan (ANOM) and siecc_alternative_method_scan (ALT) are sourced read-only and run unchanged (only the checkpoint writer is replaced by a pass-through); the package scan is compared with them cell by cell.
#   Rscript validation/legacy_equivalence_anomaly_history_synthetic.R <legacy_package_root> [--out DIR] [--seed 21] [--n 55]
args <- commandArgs(trailingOnly = TRUE); legacy_root <- args[1L]; opt <- function(nm, d) { i <- match(nm, args); if (is.na(i)) d else args[i + 1L] }; out <- opt("--out", NULL); seed <- as.integer(opt("--seed", "21")); nn <- as.integer(opt("--n", "55"))
script_arg <- sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)); root <- normalizePath(file.path(dirname(script_arg[1L]), ".."), winslash = "/")
source(file.path(root, "scripts", "load_package.R")); siw_dev_load(root); cfg <- siw_load_config(); PR <- siw_ah_protocol()
# synthetic only: every day has wet and dry participants, so no rainfall feature is constant and every weather value has participant-level noise, so the same-day residuals are not rounding noise (the original aborts on a rank-deficient model; the package records NOT_ESTIMABLE); one missing rainfall total at lag 35 as in the study data
ah_rich_rain <- function(raw, seed = 5L) { set.seed(seed); n <- nrow(raw); for (l in 1:59) { wet <- stats::rbinom(n, 1L, 0.45); raw[[sprintf("IMS_IDW_RAIN_DAYS1_L%02d", l)]] <- wet; tot <- wet * stats::rexp(n, 0.25); if (l == 35L) tot[3L] <- NA_real_; raw[[sprintf("IMS_IDW_RAIN_TOTAL_L%02d", l)]] <- tot; for (pf in c("UTCI", "MRT", "T2M", "RH", "IMS_IDW_TD_MEAN", "IMS_IDW_RH_MEAN")) { cn <- sprintf("%s_L%02d", pf, l); raw[[cn]] <- raw[[cn]] + stats::rnorm(n, 0, 0.7) } }; raw }
lenv <- new.env(parent = globalenv()); for (f in sort(list.files(file.path(legacy_root, "R"), pattern = "[.]R$", full.names = TRUE))) sys.source(f, envir = lenv); lenv$siecc_target_checkpoint_compute <- function(stage, id, fn) fn()
lcfg <- lenv$siecc_default_config(legacy_root); raw <- ah_rich_rain(siw_make_synthetic(n = nn, seed = seed, config = cfg)); dat <- siw_prepare_data(raw, cfg)
ldat <- dat; ldat$assessment_date <- as.Date("2026-01-29") + as.numeric(dat$assessment_day); ldat$assessment_date_iso <- as.character(ldat$assessment_date)                                   # the legacy data carry the date; the package the day count (a fixed offset)
tol <- cfg$tolerances; tol$name <- "cumulative"; res <- list(); timing <- list()
t0 <- proc.time()[["elapsed"]]; old <- lenv$siecc_daily_anomaly_scan(ldat, lcfg); timing$anom_legacy <- proc.time()[["elapsed"]] - t0
t0 <- proc.time()[["elapsed"]]; new <- siw_anomaly_scan(dat, cfg, PR); timing$anom_package <- proc.time()[["elapsed"]] - t0
fA <- c(.siw_ah_fields(PR, "ANOM_7080")); kA <- c("outcome", "metric", "reference_definition", "anomaly_method", "burden_direction", "window_or_lag"); fixinf <- function(d) { for (f in names(d)) if (is.numeric(d[[f]]) && any(is.infinite(d[[f]]))) d[[f]][is.infinite(d[[f]])] <- NA_real_; d }
o1 <- old$results; o1$window_or_lag <- as.integer(o1$window_or_lag); res$anom <- siw_compare_tables(fixinf(new$results[, c(kA, fA)]), fixinf(o1), kA, tol, name = "anom_vs_legacy", expected_records = nrow(o1), required_columns = fA)
catf <- c("model_id", "outcome_family", "exposure", "exposure_unit", "transformation", "model_tier", "primary_role", "status", "separation_status"); jn <- match(do.call(paste, c(o1[kA], sep = "|")), do.call(paste, c(new$results[kA], sep = "|"))); catdiff <- sum(vapply(catf, function(f) sum(as.character(new$results[[f]][jn]) != as.character(o1[[f]]) | is.na(jn)), 0))
kG <- c("metric", "method", "reference"); res$diag <- siw_compare_tables(fixinf(new$diagnostics), fixinf(old$diagnostics), kG, tol, name = "anomdiag_vs_legacy", expected_records = nrow(old$diagnostics), required_columns = c("n_total", "n_finite", "missing_fraction", "minimum", "maximum", "p01", "p99"))
t0 <- proc.time()[["elapsed"]]; oldl <- lenv$siecc_alternative_method_scan(ldat, lcfg); timing$alt_legacy <- proc.time()[["elapsed"]] - t0
t0 <- proc.time()[["elapsed"]]; newl <- siw_alt_scan(dat, cfg, PR); timing$alt_package <- proc.time()[["elapsed"]] - t0
kL <- c("outcome", "metric", "method", "feature"); res$alt <- siw_compare_tables(newl$results, oldl$results, kL, tol, name = "alt_vs_legacy", expected_records = nrow(oldl$results), required_columns = c("n", "effect", "p", "q_global", "q_outcome"))
res$pca <- siw_compare_tables(newl$pca_variance, oldl$pca_variance, c("metric", "component"), tol, name = "altpca_vs_legacy", expected_records = nrow(oldl$pca_variance), required_columns = c("variance_fraction", "cumulative_variance"))
summ <- do.call(rbind, lapply(res, function(r) r$summary)); rownames(summ) <- NULL; detail <- siw_bind_rows(lapply(res, function(r) r$detail))
print(summ[, c("reference", "status", "n_compared", "n_exact", "n_within_tolerance", "n_different", "n_unmatched", "n_nonfinite", "n_missing_required", "reason")], right = FALSE)
cat(sprintf("n = %d, seed %d. Categorical items different: %d. Runtime (s): ANOM legacy %.1f vs package %.1f; ALT legacy %.1f vs package %.1f\n", nn, seed, catdiff, timing$anom_legacy, timing$anom_package, timing$alt_legacy, timing$alt_package))
if (nrow(detail)) { cat("Largest discrepancies:\n"); print(utils::head(detail[order(-detail$abs_diff), ], 10), right = FALSE) }
if (!is.null(out)) { dir.create(out, recursive = TRUE, showWarnings = FALSE); siw_write_csv(summ, file.path(out, "legacy_equivalence_anomaly_history_summary.csv")); siw_write_csv(detail, file.path(out, "legacy_equivalence_anomaly_history_detail.csv")); siw_write_csv(data.frame(timing, categorical_different = catdiff), file.path(out, "legacy_equivalence_anomaly_history_timing.csv")) }
quit(status = as.integer(any(summ$status == "FAIL") || catdiff > 0))
